mapper.select:
SELECT s.id, s.doctor_id, s.schedule_date, s.time_slot, s.total_quota, s.booked_count, s.status, d.name AS doctorName, dept.name AS departmentName, (s.total_quota - s.booked_count) AS remainQuota FROM schedule s LEFT JOIN doctor d ON s.doctor_id = d.id LEFT JOIN department dept ON d.department_id = dept.id
AND s.doctor_id = #{query.doctorId}
AND d.department_id = #{query.departmentId}
AND s.status = #{query.status}
AND s.schedule_date >= #{query.scheduleDateStart}
AND s.schedule_date <= #{query.scheduleDateEnd}
AND s.schedule_date = #{query.scheduleDate}
ORDER BY s.schedule_date DESC, s.time_slot ASC
